import test from 'node:test';
import assert from 'node:assert/strict';
import {buildDraft,createGeometry,parseBrief,checkExport,revisionFor} from '../lib/engine.js';
import {validateGeometry} from '../lib/validation.js';
const brief={name:'Test residence',W:10,D:12,storeys:1,beds:3,baths:2,study:false,roof:false,low:false};
const geometry=()=>createGeometry(parseBrief(brief));
const codes=g=>validateGeometry(g).issues.map(i=>i.code);
test('RECONSTRUCTED — invalid input is rejected rather than silently altered',()=>{
 for(const value of [NaN,Infinity,'',null,[],true,5.9,41])assert.throws(()=>parseBrief({...brief,W:value}));
 assert.throws(()=>parseBrief({...brief,beds:2.5}));assert.throws(()=>parseBrief({...brief,study:'false'}));
 assert.throws(()=>parseBrief({...brief,storeys:4}));
});
test('RECONSTRUCTED — independent validator rejects overlapping and out-of-bounds rooms',()=>{
 const g=geometry();g.floors[0].L.R[2].x=-1;g.floors[0].L.R[2].w=20;
 assert.ok(codes(g).includes('room_overlap'));assert.ok(codes(g).includes('room_bounds'));
});
test('RECONSTRUCTED — missing entrance makes interior rooms unreachable',()=>{
 const g=geometry();g.floors[0].L.O=g.floors[0].L.O.filter(o=>o.t!=='entry');
 assert.ok(codes(g).includes('no_entrance'));assert.ok(codes(g).includes('unreachable_room'));
});
test('RECONSTRUCTED — openings need a valid host, non-overlap and valid height',()=>{
 let g=geometry();g.floors[0].L.O[0].a=[-100,0];assert.ok(codes(g).includes('opening_host'));
 g=geometry();g.floors[0].L.O.push({...structuredClone(g.floors[0].L.O[0]),id:'duplicate-location'});assert.ok(codes(g).includes('opening_overlap'));
 g=geometry();g.floors[0].L.O[0].head=4;assert.ok(codes(g).includes('opening_size'));
});
test('RECONSTRUCTED — deleting a bedroom door breaks connectivity',()=>{
 const g=geometry(),o=g.floors[0].L.O.find(o=>o.t==='door'&&!o.ext);g.floors[0].L.O=g.floors[0].L.O.filter(x=>x!==o);
 assert.ok(codes(g).includes('unreachable_room'));
});
test('RECONSTRUCTED — all outputs identify the same immutable model revision',async()=>{
 const d=await buildDraft(brief);assert.match(d.revision,/^[a-f0-9]{64}$/);
 assert.equal(d.revision,d.validation.revision);assert.equal(d.revision,d.model.revision);assert.ok(d.plans[0].svg.includes(d.revision.slice(0,12)));
 assert.notEqual(await revisionFor({...d.geometry,height:3}),d.revision);
 assert.equal((await buildDraft(brief)).revision,d.revision);
});
test('RECONSTRUCTED — export rejects stale revisions, construction exports and failed geometry',async()=>{
 const d=await buildDraft(brief);
 assert.equal(checkExport(d,'svg','old').status,409);
 assert.equal(checkExport(d,'construction',d.revision).status,422);
 assert.equal(checkExport(d,'pdf',d.revision).status,400);
 const failed={...d,validation:{...d.validation,status:'failed'}};
 assert.equal(checkExport(failed,'svg',d.revision).status,422);assert.equal(checkExport(failed,'report',d.revision),null);
});
test('RECONSTRUCTED — 3D wall faces leave actual voids for doors and windows',async()=>{
 const d=await buildDraft(brief),L=d.geometry.floors[0].L;
 for(const o of L.O){
  const w=L.S.find(w=>w.id===o.wallId),axis=Math.abs(w[0]-w[2])<1e-6?1:0;
  const position=(o.a[axis]+o.b[axis])/2,z=(o.sill+o.head)/2;
  const faces=d.model.F.filter(f=>f.sourceId===w.id);
  assert.ok(faces.length);
  assert.equal(faces.some(f=>Math.min(...f.p.map(p=>p[axis]))<position-1e-6&&Math.max(...f.p.map(p=>p[axis]))>position+1e-6&&Math.min(...f.p.map(p=>p[2]))<z-1e-6&&Math.max(...f.p.map(p=>p[2]))>z+1e-6),false,o.id);
 }
});
test('RECONSTRUCTED — input matrix either meets every implemented critical check or rejects feasibility explicitly',async()=>{
 let accepted=0,rejected=0;
 for(const [W,D]of [[6,6],[8,10],[10,12],[12,14],[14,14],[40,40]])for(const beds of [2,3,5])for(const baths of [1,2]){
  try{const d=await buildDraft({...brief,W,D,beds,baths});accepted++;assert.ok(!/NaN|Infinity/.test(d.plans[0].svg));assert.equal(d.validation.criticalCount,0);assert.equal(d.validation.constructionExportAllowed,false);assert.equal(d.validation.approval,'not_approved');}
  catch(e){rejected++;assert.equal(e.status,422);assert.ok(e.fields.fit);}
 }
 assert.ok(accepted>5);assert.ok(rejected>5);
});
test('RECONSTRUCTED — missing envelope and walls cutting through rooms are rejected',()=>{
 const g=geometry();g.floors[0].L.S=g.floors[0].L.S.filter(w=>!(w[4]&&w[1]===0&&w[3]===0));assert.ok(codes(g).includes('envelope'));
 const h=geometry(),r=h.floors[0].L.R[0],w=[r.x+r.w/2,r.y,r.x+r.w/2,r.y+r.h,0];w.id='invalid-partition';h.floors[0].L.S.push(w);assert.ok(codes(h).includes('wall_bisects_room'));
});
test('RECONSTRUCTED — untrusted project names are escaped in SVG exports',async()=>{
 const d=await buildDraft({...brief,name:'<script>alert("x")</script>'});assert.ok(!d.plans[0].svg.includes('<script>'));assert.ok(d.plans[0].svg.includes('&lt;script&gt;'));
});
test('RECONSTRUCTED — serialized geometry retains stable wall identities and validates after database round trip',()=>{
 const g=geometry(),stored=JSON.parse(JSON.stringify(g));
 assert.equal(validateGeometry(stored).criticalCount,0);
 assert.ok(stored.floors[0].L.S.every(w=>typeof w[5]==='string'));
});

test('RECONSTRUCTED — legacy saved geometry derives missing net.area and solver alternatives',async()=>{
 const {buildDraftFromGeometry}=await import('../lib/engine.js'),base=await buildDraft(brief),legacy=structuredClone(base.geometry);
 for(const floor of legacy.floors)for(const room of floor.L.R)delete room.net;
 delete legacy.solver.alternatives;
 const restored=await buildDraftFromGeometry(legacy,base.brief);
 assert.ok(restored.geometry.floors[0].L.R.filter(r=>!r.hall).every(r=>Number.isFinite(r.net.area)&&r.net.area>0));
 assert.ok(Array.isArray(restored.alternatives)&&restored.alternatives.length>0);
 assert.equal(restored.validation.criticalCount,0);
});
