test('RECONSTRUCTED — explicit open E segments are valid room connections, not missing walls',()=>{
 const g=geometry(),L=g.floors[0].L,EPS=1e-6;
 const wall=L.S.find(w=>{
  if(w[4]||L.O.some(o=>o.wallId===w[5]))return false;
  const vertical=Math.abs(w[0]-w[2])<EPS,fixed=vertical?w[0]:w[1];
  const adjacent=L.R.filter(r=>vertical?(Math.abs(r.x+r.w-fixed)<EPS||Math.abs(r.x-fixed)<EPS):(Math.abs(r.y+r.h-fixed)<EPS||Math.abs(r.y-fixed)<EPS));
  return adjacent.some(r=>r.hall)&&adjacent.some(r=>!r.hall);
 });
 assert.ok(wall,'fixture should contain an un-opened room-to-circulation partition');
 const edge=wall.slice(0,4);L.S=L.S.filter(w=>w!==wall);L.E.push(edge);
 const report=validateGeometry(g);
 assert.equal(report.criticalCount,0,JSON.stringify(report.issues));
});

test('RECONSTRUCTED — a continuous internal wall may span several adjoining room boundaries',()=>{
 const g=geometry(),L=g.floors[0].L,EPS=1e-6,groups=new Map();
 for(const w of L.S.filter(w=>!w[4])){
  const vertical=Math.abs(w[0]-w[2])<EPS,key=(vertical?'v:':'h:')+(vertical?w[0]:w[1]).toFixed(6);
  const list=groups.get(key)||[];list.push(w);groups.set(key,list);
 }
 let chosen=null,vertical=false,fixed=0,lo=0,hi=0;
 for(const [key,list] of groups){
  if(list.length<2)continue;
  const v=key.startsWith('v:'),axis=v?1:0,sorted=[...list].sort((a,b)=>Math.min(a[axis],a[axis+2])-Math.min(b[axis],b[axis+2]));
  if(sorted.every((w,i)=>i===0||Math.abs(Math.max(sorted[i-1][axis],sorted[i-1][axis+2])-Math.min(w[axis],w[axis+2]))<EPS)){
   chosen=sorted;vertical=v;fixed=Number(key.slice(2));lo=Math.min(...sorted.map(w=>Math.min(w[axis],w[axis+2])));hi=Math.max(...sorted.map(w=>Math.max(w[axis],w[axis+2])));break;
  }
 }
 assert.ok(chosen,'fixture should contain contiguous collinear partition segments');
 const ids=new Set(chosen.map(w=>w[5])),merged=vertical?[fixed,lo,fixed,hi,0,'legacy-continuous-wall']:[lo,fixed,hi,fixed,0,'legacy-continuous-wall'];
 L.S=L.S.filter(w=>!ids.has(w[5]));L.S.push(merged);
 for(const opening of L.O)if(ids.has(opening.wallId))opening.wallId=merged[5];
 const report=validateGeometry(g);
 assert.equal(report.criticalCount,0,JSON.stringify(report.issues));
});


