test('RECONSTRUCTED — room edits preserve explicit open connections elsewhere in the plan',async()=>{
 const {buildDraftFromGeometry}=await import('../lib/engine.js'),{applyGeometryEdit}=await import('../lib/editor.js');
 const base=await buildDraft(brief),legacy=structuredClone(base.geometry),L=legacy.floors[0].L,EPS=1e-6;
 legacy.schemaVersion=1;
 const wall=L.S.find(w=>{
  if(w[4]||L.O.some(o=>o.wallId===w[5]))return false;
  const vertical=Math.abs(w[0]-w[2])<EPS,fixed=vertical?w[0]:w[1];
  const adjacent=L.R.filter(r=>vertical?(Math.abs(r.x+r.w-fixed)<EPS||Math.abs(r.x-fixed)<EPS):(Math.abs(r.y+r.h-fixed)<EPS||Math.abs(r.y-fixed)<EPS));
  return adjacent.some(r=>r.hall)&&adjacent.some(r=>!r.hall);
 });
 assert.ok(wall);
 const openEdge=wall.slice(0,4);L.S=L.S.filter(w=>w!==wall);L.E.push(openEdge);
 const target=legacy.floors[0].L.R.find(r=>r.kind==='Living');assert.ok(target);
 const opened=await buildDraftFromGeometry(legacy,base.brief),room=opened.geometry.floors[0].L.R.find(r=>r.id===target.id);
 const edited=applyGeometryEdit(opened.geometry,{type:'split-room',roomId:room.id,axis:'x',position:room.x+3.25,kind:'Utility',name:'Utility store'});
 assert.ok(edited.floors[0].L.E.some(e=>e.every((v,i)=>Math.abs(v-openEdge[i])<EPS)),'open edge must remain an E segment after topology rebuild');
 const next=await buildDraftFromGeometry(edited,base.brief);
 assert.equal(next.validation.criticalCount,0);
});

