import test from 'node:test';
import assert from 'node:assert/strict';
import {normalizeSiteContext,analyzeSiteContext,SiteInputError} from '../lib/site-intelligence.js';

const square={boundary:{vertices:[{x:0,y:0},{x:6,y:0},{x:6,y:6},{x:0,y:6}],evidence:{source:'survey',status:'verified'}}};
const fails=(fn,field)=>{assert.throws(fn,e=>e instanceof SiteInputError&&(!field||e.field===field));};

test('RECONSTRUCTED — explicit null orientation and slope are treated as absent optional evidence',()=>{
 const s=normalizeSiteContext({orientation:null,slope:null});
 assert.equal(s.orientation,null);assert.equal(s.slope,null);
});

test('RECONSTRUCTED — explicit null slope direction is treated as absent',()=>{
 const s=normalizeSiteContext({slope:{percent:0,direction:null}});
 assert.equal(s.slope.percent,0);assert.equal(s.slope.direction,null);
});

test('RECONSTRUCTED — repeated adjacent boundary vertices are rejected',()=>{
 fails(()=>normalizeSiteContext({boundary:{vertices:[{x:0,y:0},{x:6,y:0},{x:6,y:0},{x:6,y:6},{x:0,y:6}]}}),'boundary.vertices.2');
});

test('RECONSTRUCTED — adjacent boundary backtracking and overlapping edges are rejected',()=>{
 fails(()=>normalizeSiteContext({boundary:{vertices:[{x:0,y:0},{x:6,y:0},{x:3,y:0},{x:3,y:6},{x:0,y:6}]}}),'boundary.vertices.1');
});

test('RECONSTRUCTED — self-intersecting parcel boundaries are rejected',()=>{
 fails(()=>normalizeSiteContext({boundary:{vertices:[{x:0,y:0},{x:6,y:6},{x:0,y:6},{x:6,y:0}]}}),'boundary');
});

test('RECONSTRUCTED — unsupported evidence source is rejected instead of silently downgraded',()=>{
 fails(()=>normalizeSiteContext({boundary:{vertices:square.boundary.vertices,evidence:{source:'survay',status:'verified'}}}),'boundary.evidence.source');
});

test('RECONSTRUCTED — unsupported evidence status is rejected instead of silently relabelled',()=>{
 fails(()=>normalizeSiteContext({boundary:{vertices:square.boundary.vertices,evidence:{source:'survey',status:'verifed'}}}),'boundary.evidence.status');
});

test('RECONSTRUCTED — empty evidence metadata remains explicitly unknown',()=>{
 const s=normalizeSiteContext({boundary:{vertices:square.boundary.vertices,evidence:{}}});
 assert.equal(s.boundary.evidence.status,'unknown');assert.equal(s.boundary.evidence.source,'unknown');
});

test('RECONSTRUCTED — a verified boundary requires an accepted professional source',()=>{
 const result=analyzeSiteContext({boundary:{vertices:square.boundary.vertices,evidence:{source:'owner_input',status:'verified'}}});
 assert.equal(result.summary.verifiedBoundary,false);
 assert.ok(result.findings.some(x=>x.code==='SITE_BOUNDARY_UNVERIFIED'));
 assert.equal(result.summary.siteFitReady,false);
});

test('RECONSTRUCTED — verified surveyed boundary is recognised but never treated as site-fit approval',()=>{
 const result=analyzeSiteContext(square);
 assert.equal(result.summary.verifiedBoundary,true);
 assert.equal(result.summary.siteFitReady,false);
 assert.equal(result.summary.geometryMayBeGeneratedFromSite,false);
 assert.equal(result.summary.regulatoryComplianceVerified,false);
});

