import assert from 'node:assert/strict';
import { assessSiteFit } from '../lib/site-fit.js';
const square=(size=20)=>({boundary:{vertices:[{x:0,y:0},{x:size,y:0},{x:size,y:size},{x:0,y:size}],evidence:{status:'provided',source:'owner_input'}}});
const geometry=(W=10,D=12)=>({floors:[{L:{W,D}}]});
test('RECONSTRUCTED — rectangular footprint candidates fit inside a larger parcel',()=>{
 const source=geometry(),before=structuredClone(source),result=assessSiteFit(square(20),source);
 assert.equal(result.status,'candidate_found');
 assert.ok(result.candidates.length>0);
 assert.equal(result.geometryChanged,false);
 assert.deepEqual(source,before);
 assert.equal(result.setbacksApplied,false);
 assert.equal(result.regulatoryComplianceVerified,false);
});
test('RECONSTRUCTED — missing boundary blocks fit assessment',()=>{
 const result=assessSiteFit({},geometry());
 assert.equal(result.status,'blocked');
 assert.equal(result.decision,'boundary_required');
 assert.equal(result.candidates.length,0);
});
test('RECONSTRUCTED — footprint larger than parcel returns no candidate, not a buildability verdict',()=>{
 const result=assessSiteFit(square(9),geometry(10,12));
 assert.equal(result.status,'no_candidate_found');
 assert.match(result.decision,/no_footprint_candidate/);
 assert.equal(result.professionalApprovalGranted,false);
});
test('RECONSTRUCTED — concave parcel notch cannot be bridged by a bounding-box-only placement',()=>{
 const site={boundary:{vertices:[{x:0,y:0},{x:20,y:0},{x:20,y:10},{x:10,y:10},{x:10,y:20},{x:0,y:20}],evidence:{status:'provided',source:'owner_input'}}};
 const result=assessSiteFit(site,geometry(11,11));
 assert.equal(result.status,'no_candidate_found');
});
test('RECONSTRUCTED — recorded constraints are explicitly not applied',()=>{
 const site=square(20);site.constraints=[{type:'easement',side:'east',distanceM:3,evidence:{status:'provided',source:'owner_input'}}];
 const result=assessSiteFit(site,geometry());
 assert.ok(result.findings.some(x=>x.code==='RECORDED_CONSTRAINTS_NOT_APPLIED'));
 assert.equal(result.setbacksApplied,false);
});
test('RECONSTRUCTED — multi-storey geometry is outside the current site-fit scope',()=>{
 const result=assessSiteFit(square(20),{floors:[{L:{W:10,D:12}},{L:{W:10,D:12}}]});
 assert.equal(result.status,'blocked');
 assert.equal(result.decision,'unsupported_geometry_scope');
});

test('RECONSTRUCTED — outside footprint includes the modeled exterior-wall allowance',()=>{
 const result=assessSiteFit(square(10),geometry(10,10));
 assert.equal(result.status,'no_candidate_found');
 const larger=assessSiteFit(square(10.8),geometry(10,10));
 assert.equal(larger.status,'candidate_found');
 assert.equal(larger.geometry.exteriorFootprintWidthM,10.3);
 assert.equal(larger.geometry.exteriorFootprintDepthM,10.3);
});

test('RECONSTRUCTED — thicker edited exterior walls expand the checked footprint',()=>{
 const g=geometry(10,10),wall=[0,0,0,10,true];wall.thickness=.5;g.floors[0].L.S=[wall];
 const tight=assessSiteFit(square(10.4),g);
 const roomy=assessSiteFit(square(11),g);
 assert.equal(tight.status,'no_candidate_found');
 assert.equal(roomy.status,'candidate_found');
 assert.equal(roomy.geometry.exteriorWallAllowanceM,.5);
});

test('RECONSTRUCTED — verified exclusion polygons block candidate placements',()=>{
 const site=square(20);site.exclusionZones=[{type:'hazard',vertices:[{x:0,y:0},{x:19.9,y:0},{x:19.9,y:19.9},{x:0,y:19.9}],evidence:{status:'verified',source:'survey'}}];
 const result=assessSiteFit(site,geometry());
 assert.equal(result.status,'no_candidate_found');
 assert.equal(result.verifiedExclusionZonesApplied,1);
 assert.equal(result.exclusionZonesApplied,true);
});
test('RECONSTRUCTED — unverified exclusion polygons are disclosed but not applied',()=>{
 const site=square(20);site.exclusionZones=[{type:'easement',vertices:[{x:0,y:0},{x:19.9,y:0},{x:19.9,y:19.9},{x:0,y:19.9}],evidence:{status:'provided',source:'owner_input'}}];
 const result=assessSiteFit(site,geometry());
 assert.equal(result.status,'candidate_found');
 assert.equal(result.unverifiedExclusionZonesNotApplied,1);
 assert.ok(result.findings.some(x=>x.code==='EXCLUSION_ZONE_UNVERIFIED_NOT_APPLIED'));
});
test('RECONSTRUCTED — verified exclusion polygon leaves other candidate locations available',()=>{
 const site=square(30);site.exclusionZones=[{type:'protected_tree',vertices:[{x:12,y:12},{x:18,y:12},{x:18,y:18},{x:12,y:18}],evidence:{status:'verified',source:'professional_observation'}}];
 const result=assessSiteFit(site,geometry());
 assert.equal(result.status,'candidate_found');
 assert.equal(result.verifiedExclusionZonesApplied,1);
 assert.ok(result.candidates.every(c=>c.origin.x+c.widthM<=12||c.origin.x>=18||c.origin.y+c.depthM<=12||c.origin.y>=18),'no candidate may overlap the protected polygon');
});

tests/multistorey-validation.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import { validateMultiStorey } from '../lib/multistorey-validation.js';

const floor = (id, elevation) => ({
  id, elevation, coordinateFrameId: 'building-global',
  footprintRelationship: { type: 'aligned' },
  floorToFloorHeightM: elevation === 0 ? undefined : 3,
  L: { W: 20, D: 20, R: [{ id: id + '-room', x: 0, y: 0, w: 20, h: 20 }], S: [], O: [] }
});
const valid = () => {
  const a = floor('f0', 0), b = floor('f1', 3);
  const stair = {
    id: 'stair-0', from: 'f0', to: 'f1', fromRoomId: 'f0-room', toRoomId: 'f1-room',
    x: 2, y: 2, w: 3, h: 4, rise: 3,
    headroom: {
      clearanceM: 2.1, measurementId: 'scan-001', method: 'laser_scan',
      measurementPoints: [{x:2,y:2,z:0},{x:3,y:3,z:0}],
      obstructionReview: {status:'clear',reviewId:'clearance-review-001'}
    }
  };
  b.void = { x: 2, y: 2, w: 3, h: 4 };
  return {
    units: 'm', coordinateFrameId: 'building-global', floors: [a,b], stairs: [stair],
    designRuleset: {id:'TEST-RULES',version:'1.0',minimumStairHeadroomM:2,source:'Test ruleset',sourceUrl:'https://example.invalid/rules'},
    egress: {exits:[{id:'exit-0',roomId:'f0-room',type:'exterior_exit'}],edges:[],ruleset:{id:'TEST-EGRESS',version:'1.0',sourceUrl:'https://example.invalid/egress'}}
  };
};
const issue = (result, code) => result.issues.some(x => x.code === code);
const check = (result, name) => result.checks.find(x => x.name === name)?.status;

test('baseline: valid multi-storey geometry and traceable headroom evidence', () => {
  const r = validateMultiStorey(valid());
  assert.equal(r.issues.filter(x => x.severity === 'critical').length, 0);
  assert.equal(check(r,'measured_stair_headroom'),'passed');
  assert.equal(check(r,'escape_route_graph'),'passed');
  assert.equal(check(r,'egress_regulatory_screening'),'not_checked');
});
test('baseline: non-monotonic elevations and inconsistent floor height are rejected', () => {
  const g=valid(); g.floors[1].elevation=2.5;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'floor_height_mismatch'));
});
test('baseline: headroom below an explicitly sourced ruleset threshold fails', () => {
  const g=valid(); g.stairs[0].headroom.clearanceM=1.8;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'stair_headroom_below_threshold'));
});
test('1: missing building coordinate frame fails closed', () => {
  const g=valid(); delete g.coordinateFrameId;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'building_coordinate_frame_missing'));
  assert.equal(check(r,'floor_coordinate_and_element_identity'),'failed');
});
test('2: every floor must match the building coordinate frame', () => {
  const g=valid(); g.floors[1].coordinateFrameId='other-frame';
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'floor_coordinate_frame_mismatch'));
});
test('3: room IDs must be non-empty and unique across floors', () => {
  const duplicate=valid(); duplicate.floors[1].L.R[0].id='f0-room';
  const duplicateResult=validateMultiStorey(duplicate);
  assert.ok(issue(duplicateResult,'room_identity_duplicate'));
  assert.equal(check(duplicateResult,'room_identity_and_geometry'),'failed');
  const empty=valid(); empty.floors[1].L.R[0].id=' ';
  const emptyResult=validateMultiStorey(empty);
  assert.ok(issue(emptyResult,'room_identity_invalid'));
});
test('4: room dimensions must be finite and positive', () => {
  const g=valid(); g.floors[1].L.R[0].w=Infinity; g.floors[1].L.R[0].h=-1;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'room_geometry_invalid'));
});
test('5: stair IDs must be unique', () => {
  const g=valid(); g.stairs.push({...g.stairs[0]});
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'stair_identity_duplicate'));
});
test('6: null stair entries return structured failures rather than throwing', () => {
  const g=valid(); g.stairs=[null];
  const r=validateMultiStorey(g);
  assert.ok(Array.isArray(r.issues));
  assert.ok(issue(r,'stair_identity_invalid'));
  assert.notEqual(check(r,'measured_stair_headroom'),'passed');
});
test('7: missing stair ID is rejected', () => {
  const g=valid(); delete g.stairs[0].id;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'stair_identity_invalid'));
});
test('8: a stair connecting a non-adjacent or unknown floor is rejected as an extra connection', () => {
  const g=valid(); g.stairs[0].from='missing-floor';
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'stair_floor_pair_invalid'));
  assert.ok(issue(r,'vertical_connection_extras'));
  assert.equal(check(r,'vertical_circulation_connections'),'failed');
});
test('9: multiple legitimate staircases may connect the same adjacent floor pair', () => {
  const g=valid();
  const second={...g.stairs[0],id:'stair-1',x:10,y:10,fromRoomId:'f0-room',toRoomId:'f1-room'};
  g.stairs.push(second);
  g.floors[1].voids=[
    {stairId:'stair-0',x:2,y:2,w:3,h:4},
    {stairId:'stair-1',x:10,y:10,w:3,h:4}
  ];
  const r=validateMultiStorey(g);
  assert.equal(check(r,'vertical_circulation_connections'),'passed');
  assert.ok(!issue(r,'vertical_connection_extras'));
});
test('10: landing-room associations are required even without egress evidence', () => {
  const g=valid(); delete g.egress; delete g.stairs[0].fromRoomId;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'stair_landing_association_invalid'));
});
test('11: an unmatched stair without headroom evidence cannot receive a passed headroom status', () => {
  const g=valid(); g.stairs[0].from='unknown-floor'; delete g.stairs[0].headroom;
  const r=validateMultiStorey(g);
  assert.notEqual(check(r,'measured_stair_headroom'),'passed');
  assert.ok(issue(r,'stair_headroom_unmeasured'));
});
test('12: duplicate or empty floor identities are rejected', () => {
  const g=valid(); g.floors[1].id='';
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'floor_identity'));
});
test('13: malformed floor entries return structured failure rather than throwing', () => {
  const g=valid(); g.floors[1]=null;
  const r=validateMultiStorey(g);
  assert.ok(Array.isArray(r.issues));
  assert.ok(issue(r,'floor_record_invalid'));
});
test('14: a missing stairs collection is not treated as a successful circulation check', () => {
  const g=valid(); delete g.stairs;
  const r=validateMultiStorey(g);
  assert.notEqual(check(r,'vertical_circulation_connections'),'passed');
});
test('26: egress edges without a matching physical opening or validated stair are rejected', () => {
  const g=valid(); g.egress.edges=[{from:'f0-room',to:'f1-room'}];
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_edge_unverified'));
  assert.equal(check(r,'escape_route_graph'),'failed');
});
test('27: delimiter-like room IDs remain distinct graph nodes', () => {
  const g=valid();
  g.floors[0].L.R.push({id:'f0::room-extra',x:1,y:1,w:2,h:2});
  g.floors[1].L.R.push({id:'f1::room-extra',x:4,y:4,w:2,h:2});
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_unreachable_room'));
});
test('28: malformed egress edge collection is a structured failure', () => {
  const g=valid(); g.egress.edges={from:'f0-room',to:'f1-room'};
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_structure_invalid'));
  assert.equal(check(r,'escape_route_graph'),'failed');
});
test('29: exit records must reference an existing room and exterior exit type', () => {
  const g=valid(); g.egress.exits=[{id:'bad-exit',roomId:'missing',type:'interior_door'}];
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_exit_invalid'));
});
test('30: an unverified stair cannot create a cross-floor escape path', () => {
  const g=valid(); delete g.stairs[0].headroom;
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_unreachable_room'));
  assert.equal(check(r,'escape_route_graph'),'failed');
});
test('31: duplicate egress edges are rejected', () => {
  const g=valid();
  g.egress.edges=[
    {from:'f0-room',to:'f1-room',stairId:'stair-0'},
    {from:'f0-room',to:'f1-room',stairId:'stair-0'}
  ];
  const r=validateMultiStorey(g);
  assert.ok(issue(r,'egress_edge_invalid'));
});
test('32: null top-level input returns a structured failure', () => {
  const r=validateMultiStorey(null);
  assert.ok(Array.isArray(r.issues));
  assert.ok(issue(r,'building_input_invalid'));
});
test('33: missing floors returns a structured failure', () => {
  const r=validateMultiStorey({units:'m'});
  assert.ok(issue(r,'floors_invalid'));
});
test('34: malformed top-level floor collection returns a structured failure', () => {
  const r=validateMultiStorey({floors:'not-an-array'});
  assert.ok(issue(r,'floors_invalid'));
});

