import test from 'node:test';
import assert from 'node:assert/strict';
import {inspectOverheadGeometry,OVERHEAD_ELEMENT_TYPES} from '../lib/overhead-geometry.js';
const base=()=>({
 floors:[{id:'floor-1',coordinateFrameId:'frame-1',units:'m'},{id:'floor-2',coordinateFrameId:'frame-2',units:'m'}],
 coordinateFrames:[{id:'frame-1',floorId:'floor-1',units:'m'},{id:'frame-2',floorId:'floor-2',units:'m'}],
 overheadElements:[
  {id:'beam-1',type:'beam',floorId:'floor-1',coordinateFrameId:'frame-1',units:'m',geometry:{type:'box3d',min:{x:1,y:1,z:2},max:{x:2,y:2,z:2.2}},source:{kind:'survey',referenceId:'survey-7',revision:'rev-3'}},
  {id:'soffit-1',type:'soffit',floorId:'floor-1',coordinateFrameId:'frame-1',units:'m',geometry:{type:'box3d',min:{x:2,y:1,z:2.2},max:{x:3,y:2,z:2.4}},source:{kind:'survey',referenceId:'survey-7',revision:'rev-3'}},
  {id:'drop-1',type:'ceiling_drop',floorId:'floor-1',coordinateFrameId:'frame-1',units:'m',geometry:{type:'box3d',min:{x:3,y:1,z:2},max:{x:4,y:2,z:2.3}},source:{kind:'model',referenceId:'model-2',revision:'rev-1'}},
  {id:'edge-1',type:'stair_opening_edge',floorId:'floor-1',coordinateFrameId:'frame-1',units:'m',geometry:{type:'polyline3d',points:[{x:4,y:1,z:2.7},{x:4,y:2,z:2.7}]},source:{kind:'survey',referenceId:'opening-1',revision:'rev-2'}}
 ],
 stairs:[{id:'stair-1',from:'floor-1',to:'floor-2',geometryParts:[
  {id:'flight-geometry-1',kind:'flight',floorId:'floor-1',coordinateFrameId:'frame-1',units:'m',geometry:{type:'box3d',min:{x:5,y:1,z:0},max:{x:7,y:3,z:2.8}}},
  {id:'landing-geometry-1',kind:'landing',floorId:'floor-2',coordinateFrameId:'frame-2',units:'m',geometry:{type:'box3d',min:{x:7,y:1,z:1.3},max:{x:8,y:3,z:1.5}}}
 ],path:{flights:[{id:'flight-segment-1',geometryRef:'flight-geometry-1'}],landings:[{id:'landing-segment-1',geometryRef:'landing-geometry-1'}]}}]
});
test('Stage 2A accepts all four overhead element types with traceable 3D geometry',()=>{assert.deepEqual(OVERHEAD_ELEMENT_TYPES,['beam','soffit','ceiling_drop','stair_opening_edge']);const r=inspectOverheadGeometry(base());assert.equal(r.status,'model_valid');assert.deepEqual(r.issues,[]);assert.equal(r.elements,4);});
test('Stage 2A rejects missing overhead element IDs',()=>{const m=base();delete m.overheadElements[0].id;const r=inspectOverheadGeometry(m);assert.equal(r.status,'invalid');assert.ok(r.issues.some(i=>i.code==='element_id_missing'));});
test('Stage 2A rejects an overhead element linked to the wrong coordinate frame',()=>{const m=base();m.overheadElements[0].coordinateFrameId='frame-2';const r=inspectOverheadGeometry(m);assert.equal(r.status,'invalid');assert.ok(r.issues.some(i=>i.code==='coordinate_frame_mismatch'));});
test('Stage 2A rejects unresolved stair path geometry references',()=>{const m=base();m.stairs[0].path.flights[0].geometryRef='missing-flight';const r=inspectOverheadGeometry(m);assert.equal(r.status,'invalid');assert.ok(r.issues.some(i=>i.code==='stair_path_reference_unresolved'));});
test('Stage 2A preserves legacy projects without overhead data as not_checked',()=>{const legacy={floors:[{id:'floor-1'}],stairs:[]};const before=structuredClone(legacy);const r=inspectOverheadGeometry(legacy);assert.equal(r.status,'not_checked');assert.deepEqual(r.issues,[]);assert.deepEqual(legacy,before);});

