import test from 'node:test';
import assert from 'node:assert/strict';
import {assessStairClearance} from '../lib/stair-clearance.js';
import {assessRegulatoryClearance} from '../lib/regulatory-ruleset.js';
const p=(x,y,z)=>({x,y,z});
const box=(id,min,max,type='beam')=>({id,type,floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min,max},source:{kind:'survey',referenceId:id,revision:'r1'}});
const plane=(id,z,a=0,b=0)=>({id,type:'soffit',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'plane3d',a,b,c:z,footprint:[p2(-2,-2),p2(8,-2),p2(8,2),p2(-2,2)]},source:{kind:'survey',referenceId:id,revision:'r1'}});
const p2=(x,y)=>({x,y});
function base(){
 const parts=[
  {id:'approach',kind:'approach',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min:p(-2,-2,-1),max:p(8,2,4)},clearancePath:{centerline3d:[p(-1,0,0),p(0,0,0)],widthM:1}},
  {id:'flight',kind:'flight',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min:p(-2,-2,-1),max:p(8,2,4)},clearancePath:{centerline3d:[p(0,0,0),p(4,0,2)],widthM:1}},
  {id:'transition',kind:'transition',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min:p(-2,-2,-1),max:p(8,2,4)},clearancePath:{centerline3d:[p(4,0,2),p(4.5,0,2)],widthM:1}},
  {id:'landing',kind:'landing',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min:p(-2,-2,-1),max:p(8,2,4)},clearancePath:{centerline3d:[p(4.5,0,2),p(5.5,0,2)],widthM:1}},
  {id:'opening-edge-path',kind:'opening_edge',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'box3d',min:p(-2,-2,-1),max:p(8,2,4)},clearancePath:{centerline3d:[p(5.5,0,2),p(6,0,2)],widthM:1}}
 ];
 const refs=parts.map(x=>({id:x.id,geometryRef:x.id}));
 const stair={id:'stair-1',from:'f0',to:'f1',geometryParts:parts,path:{sequence:refs,flights:[refs[1]],landings:[refs[3]]},
  headroom:{clearanceM:1,measurementId:'scan-1',method:'laser_scan',measurementPoints:[p(0,0,0),p(6,0,2)],geometryRevision:'rev-1'}};
 return {floors:[{id:'f0',coordinateFrameId:'frame',units:'m'},{id:'f1',coordinateFrameId:'frame-1',units:'m'}],coordinateFrames:[{id:'frame',floorId:'f0',units:'m'},{id:'frame-1',floorId:'f1',units:'m'}],geometryRevision:'rev-1',clearanceMeasurementToleranceM:0.02,
  overheadGeometryReview:{status:'complete',reviewId:'review-1',geometryRevision:'rev-1'},
  overheadElements:[plane('ceiling',3)],designRuleset:{id:'TEST',version:'1',minimumStairHeadroomM:0.5,source:'test fixture',sourceUrl:'https://example.invalid/rules'},
  stairs:[stair]};
}
const assess=g=>assessStairClearance(g,g.stairs[0]);
test('Stage 2B: clear stair computes minimum continuously across approach, flight, transition, landing and opening edge',()=>{
 const g=base(),r=assess(g);assert.equal(r.status,'passed');assert.ok(Math.abs(r.geometryDerivedClearanceM-1)<1e-8);assert.equal(r.measuredClearanceM,1);assert.equal(r.measurementStatus,'current');assert.deepEqual(r.releaseBlockers,[]);
});
test('Stage 2B: beam directly over a flight determines the minimum clearance',()=>{
 const g=base();g.overheadElements.push(box('flight-beam',p(1.5,-0.4,2.2),p(2.5,0.4,2.5)));g.stairs[0].headroom.clearanceM=0.95;const r=assess(g);assert.equal(r.status,'passed');assert.ok(Math.abs(r.geometryDerivedClearanceM-0.95)<1e-8);assert.ok(r.obstructionIds.includes('flight-beam'));
});
test('Stage 2B: beam over a landing is included in the minimum',()=>{
 const g=base();g.overheadElements.push(box('landing-beam',p(4.7,-0.4,2.6),p(5.2,0.4,2.8)));const r=assess(g);assert.ok(Math.abs(r.geometryDerivedClearanceM-0.6)<1e-8);assert.ok(r.obstructionIds.includes('landing-beam'));
});
test('Stage 2B: soffit crossing the path is continuously intersected',()=>{
 const g=base();g.overheadElements=[plane('crossing-soffit',2.8)];const r=assess(g);assert.ok(Math.abs(r.geometryDerivedClearanceM-0.8)<1e-8);
});
test('Stage 2B: local ceiling drop controls the minimum where it overlaps the path',()=>{
 const g=base();g.overheadElements.push(box('drop',p(1.4,-0.3,2.0),p(2.1,0.3,2.3),'ceiling_drop'));const r=assess(g);assert.ok(Math.abs(r.geometryDerivedClearanceM-0.95)<1e-8);assert.ok(r.obstructionIds.includes('drop'));
});
test('Stage 2B: stair-opening edge crossing the usable path is reported as an obstruction',()=>{
 const g=base();g.overheadElements.push({id:'opening-edge-conflict',type:'stair_opening_edge',floorId:'f0',coordinateFrameId:'frame',units:'m',geometry:{type:'polyline3d',points:[p(2,0,0.8),p(2,0,1.4)]},source:{kind:'survey',referenceId:'edge',revision:'r1'}});const r=assess(g);assert.ok(r.obstructionIds.includes('opening-edge-conflict'));assert.ok(r.geometryDerivedClearanceM<=0);
});
test('Stage 2B: an obstruction outside the usable path does not create a false positive',()=>{
 const g=base();g.overheadElements.push(box('outside',p(1,1.1,0.2),p(3,1.5,0.4)));const r=assess(g);assert.equal(r.status,'passed');assert.ok(!r.obstructionIds.includes('outside'));assert.ok(Math.abs(r.geometryDerivedClearanceM-1)<1e-8);
});
test('Stage 2B: a narrow obstruction between arbitrary sample points is still detected continuously',()=>{
 const g=base();g.overheadElements.push(box('narrow',p(1.99,-0.08,1.45),p(2.01,0.08,1.6)));const r=assess(g);assert.ok(r.obstructionIds.includes('narrow'));assert.ok(Math.abs(r.geometryDerivedClearanceM-0.445)<1e-8);
});
test('Stage 2B: missing overhead or path geometry is not_checked and a release blocker',()=>{
 const g=base();g.overheadElements=[];let r=assess(g);assert.equal(r.status,'not_checked');assert.ok(r.releaseBlockers.length);assert.ok(r.geometryDerivedClearanceM===null);
 const h=base();delete h.stairs[0].path.sequence;r=assess(h);assert.equal(r.status,'not_checked');assert.ok(r.releaseBlockers.length);
});
test('Stage 2B: computed-versus-measured disagreement beyond declared tolerance fails',()=>{
 const g=base();g.stairs[0].headroom.clearanceM=1.3;const r=assess(g);assert.equal(r.status,'failed');assert.ok(r.issues.some(i=>i.code==='computed_measured_disagreement'));assert.ok(r.releaseBlockers.some(i=>i.code==='computed_measured_disagreement'));
});
test('Stage 2B: measurement is stale when the geometry revision changes',()=>{
 const g=base();g.stairs[0].headroom.geometryRevision='old-revision';const r=assess(g);assert.equal(r.measurementStatus,'stale');assert.ok(r.releaseBlockers.some(i=>i.code==='measurement_stale'));assert.notEqual(r.status,'passed');
});
test('Stage 2B: sloped soffit uses its continuous plane, not a horizontal bounding box',()=>{
